        if x == k {
            return true
        }
        if x < k {
            cur = l[cur as usize]
        } else {
            cur = r[cur as usize]
        }
    }
    false
}

fn del(keys: &mut Vec<int>, l: &mut Vec<int>, r: &mut Vec<int>, node: int, x: int) -> int {
    if node < 0 {
        return -1
    }
    let n = node as usize
    if x < keys[n] {
        let c = l[n]
        let v = del(keys, l, r, c, x)
        l[n] = v
        return node
    }
    if x > keys[n] {
        let c = r[n]
        let v = del(keys, l, r, c, x)
        r[n] = v
        return node
    }
    if l[n] < 0 {
        return r[n]
    }
    if r[n] < 0 {
        return l[n]
    }
    let mut s = r[n]
    while l[s as usize] >= 0 {
        s = l[s as usize]
    }
    let sk = keys[s as usize]
    keys[n] = sk
    let c = r[n]
    let v = del(keys, l, r, c, sk)
    r[n] = v
    node
}

fn walk(keys: &Vec<int>, l: &Vec<int>, r: &Vec<int>, node: int, out: &mut Vec<string>) {
    if node < 0 {
        return
    }
    let n = node as usize
    walk(keys, l, r, l[n], out)
    out.push(keys[n].to_string())
    walk(keys, l, r, r[n], out)
}

fn height(l: &Vec<int>, r: &Vec<int>, node: int) -> int {
    if node < 0 {
        return 0
    }
    let a = height(l, r, l[node as usize])
    let b = height(l, r, r[node as usize])
    if a > b {
        return a + 1
    }
    b + 1
}

